'')==='both'?'selected':'' ?>>İkisi de</option></select><select name="license_status"><option value="">Tüm lisanslar</option><option value="free" <?= ($filters['license_status']??'')==='free'?'selected':'' ?>>Boşta</option><option value="active" <?= ($filters['license_status']??'')==='active'?'selected':'' ?>>Aktif</option><option value="unlicensed" <?= ($filters['license_status']??'')==='unlicensed'?'selected':'' ?>>Lisanssız</option><option value="unknown" <?= ($filters['license_status']??'')==='unknown'?'selected':'' ?>>Belirsiz</option></select><button class="btn btn-dark">Filtrele</button></form><section class="panel admin-table-wrap"><table class="admin-table"><thead><tr><th>Futbolcu</th><th>Konum</th><th>Mevki</th><th>Amaç</th><th>Lisans</th><th>Öz-beyan</th><th>Durum</th><th>Güncelleme</th><th></th></tr></thead><tbody><?php foreach($ads as $ad):?><tr><td><strong><?= htmlspecialchars((string)$ad['display_name']) ?></strong><small>@<?= htmlspecialchars((string)($ad['username']?:'oyuncu-'.$ad['user_id'])) ?></small></td><td><?= htmlspecialchars(trim((string)($ad['district']??'').', '.(string)$ad['province'],', ')) ?></td><td><?= htmlspecialchars((string)$ad['primary_position']) ?></td><td><?= htmlspecialchars((string)($ad['profile_intent']??'team_search')) ?></td><td><?= htmlspecialchars((string)$ad['license_status']) ?></td><td><?= (int)$ad['declared_matches'] ?> M · <?= (int)$ad['declared_goals'] ?> G · <?= (int)$ad['declared_assists'] ?> A</td><td><span class="admin-status <?= htmlspecialchars((string)$ad['status']) ?>"><?= htmlspecialchars((string)$ad['status']) ?></span></td><td><?= htmlspecialchars((string)$ad['updated_at']) ?></td><td><a href="/admin/amator-ilan/<?= (int)$ad['id'] ?>">İncele</a></td></tr><?php endforeach;?><?php if(!$ads):?><tr><td colspan="9">Bu filtrelerde oyuncu profili yok.</td></tr><?php endif;?></tbody></table></section></main><?php require __DIR__.'/../layouts/admin-footer.php'; ?>
